#!/usr/bin/env bash
# Install GUI For Duplicity for the current user:
#   ~/.local/bin/{gui-for-duplicity,engine-cli}
#   ~/.local/share/applications/gui-for-duplicity.desktop
#   ~/.local/share/icons/hicolor/128x128/apps/gui-for-duplicity.png
# The two binaries are installed side-by-side; systemd units generated by
# the tool locate engine-cli next to the running executable.
set -euo pipefail

cd "$(dirname "$0")/.."

BIN_DIR="${HOME}/.local/bin"
APP_DIR="${HOME}/.local/share/applications"
ICON_DIR="${HOME}/.local/share/icons/hicolor/128x128/apps"

for binary in target/release/gui-for-duplicity target/release/engine-cli; do
    if [ ! -x "$binary" ]; then
        echo "Missing $binary — run 'cargo build --release' first." >&2
        exit 1
    fi
done

mkdir -p "$BIN_DIR" "$APP_DIR" "$ICON_DIR"
install -m 755 target/release/gui-for-duplicity "$BIN_DIR/"
install -m 755 target/release/engine-cli "$BIN_DIR/"
install -m 644 packaging/gui-for-duplicity.desktop "$APP_DIR/"
install -m 644 app/src-tauri/icons/icon.png "$ICON_DIR/gui-for-duplicity.png"

# Refresh caches so the menu entry appears without a re-login.
update-desktop-database "$APP_DIR" 2>/dev/null || true
gtk-update-icon-cache -f -t "${HOME}/.local/share/icons/hicolor" 2>/dev/null || true

echo "Installed:"
echo "  $BIN_DIR/gui-for-duplicity"
echo "  $BIN_DIR/engine-cli"
echo "  $APP_DIR/gui-for-duplicity.desktop"
echo
echo "Note: systemd units created earlier while running from the build"
echo "directory keep their old path until the profile's schedule is"
echo "re-enabled (the GUI's 'Enable schedule' button refreshes them)."
